#ifdef NDEBUG
#undef NDEBUG
#endif /* NDEBUG */

#include <cmath>
#include <array>
#include <vector>
#include <string>
#include <cstdlib>
#include <iostream>
#include "TFEL/Tests/TestCase.hxx"
#include "TFEL/Tests/TestProxy.hxx"
#include "TFEL/Tests/TestManager.hxx"
#include "TFEL/Math/tmatrix.hxx"
#include "TFEL/Math/stensor.hxx"
#include "TFEL/Math/tensor.hxx"
#include "TFEL/Math/st2tost2.hxx"
#include "TFEL/Math/t2tot2.hxx"
#include "TFEL/System/ExternalLibraryManager.hxx"

struct GenericBehaviourRotationFunctionsTest final
    : public tfel::tests::TestCase {
  GenericBehaviourRotationFunctionsTest()
      : tfel::tests::TestCase("MFront",
                              "GenericBehaviourRotationFunctionsTest"),
        library([] {
          const auto e = ::getenv("MFrontGenericRotationFunctionsBehavioursBuildPath");
          return e == nullptr ? std::string{} : e;
        }()) {
    using namespace tfel::math;
    // rotation matrix from the global frame to the material frame
    const auto c1 = std::cos(real(0.3));
    const auto s1 = std::sin(real(0.3));
    const auto c2 = std::cos(real(1.1));
    const auto s2 = std::sin(real(1.1));
    const auto rz = tmatrix<3u, 3u, real>{c1, -s1, 0, s1, c1, 0, 0, 0, 1};
    const auto rx = tmatrix<3u, 3u, real>{1, 0, 0, 0, c2, -s2, 0, s2, c2};
    this->R = rz * rx;
    // the rotation functions expect this matrix in column-major format
    for (unsigned short i = 0; i != 3; ++i) {
      for (unsigned short j = 0; j != 3; ++j) {
        this->rv[i + 3 * j] = this->R(i, j);
      }
    }
  }  // end of GenericBehaviourRotationFunctionsTest

  tfel::tests::TestResult execute() override {
    using namespace tfel::math;
    using namespace tfel::system;
    auto& elm = ExternalLibraryManager::getExternalLibraryManager();
    const auto f =
        std::string{"OrthotropicRotationFunctionsTest_Tridimensional"};
    // gradients: e (symmetric tensor) and f (tensor)
    const auto r_g = transpose(this->R);
    this->check(
        elm.getGenericBehaviourRotateArrayOfGradientsFunction(
            this->library, f + "_rotateArrayOfGradients"),
        [&r_g](real* const dest, const real* const src) {
          map<stensor<3u, real>>(dest) =
              change_basis(stensor<3u, real>{src}, r_g);
          map<tensor<3u, real>>(dest + 6) =
              change_basis(tensor<3u, real>{src + 6}, r_g);
        },
        15u);
    // thermodynamic forces: sig (symmetric tensor) and tau (tensor)
    const auto& r = this->R;
    this->check(
        elm.getGenericBehaviourRotateArrayOfThermodynamicForcesFunction(
            this->library, f + "_rotateArrayOfThermodynamicForces"),
        [&r](real* const dest, const real* const src) {
          map<stensor<3u, real>>(dest) =
              change_basis(stensor<3u, real>{src}, r);
          map<tensor<3u, real>>(dest + 6) =
              change_basis(tensor<3u, real>{src + 6}, r);
        },
        15u);
    // tangent operator blocks: dsig_dde, dtau_ddf and dsig_ddT
    this->check(
        elm.getGenericBehaviourRotateArrayOfTangentOperatorBlocksFunction(
            this->library, f + "_rotateArrayOfTangentOperatorBlocks"),
        [&r](real* const dest, const real* const src) {
          map<st2tost2<3u, real>>(dest) =
              change_basis(st2tost2<3u, real>{src}, r);
          map<t2tot2<3u, real>>(dest + 36) =
              change_basis(t2tot2<3u, real>{src + 36}, r);
          map<stensor<3u, real>>(dest + 117) =
              change_basis(stensor<3u, real>{src + 117}, r);
        },
        123u);
    return this->result;
  }  // end of execute

 private:
  //! \brief a simple alias
  using real = mfront_gb_real;
  /*!
   * \brief check that a rotation function of an array of integration points
   * rotates each point, with distinct and identical source and destination.
   * \param[in] rotate_array: tested function
   * \param[in] rotate: reference rotation of the values of one point
   * \param[in] s: number of values per point
   */
  template <typename ArrayRotationFunction, typename RotationFunction>
  void check(const ArrayRotationFunction rotate_array,
             const RotationFunction& rotate,
             const std::size_t s) {
    // number of integration points
    constexpr auto n = mfront_gb_size_type{3};
    auto src = std::vector<real>(n * s);
    for (std::size_t i = 0; i != src.size(); ++i) {
      src[i] = std::sin(static_cast<real>(i + 1));
    }
    auto expected = std::vector<real>(n * s);
    for (std::size_t p = 0; p != n; ++p) {
      rotate(expected.data() + p * s, src.data() + p * s);
    }
    auto dest = std::vector<real>(n * s, real(0));
    rotate_array(dest.data(), src.data(), this->rv.data(), n);
    TFEL_TESTS_CHECK(areEqual(dest, expected));
    rotate_array(src.data(), src.data(), this->rv.data(), n);
    TFEL_TESTS_CHECK(areEqual(src, expected));
  }  // end of check
  //! \return if the given values are equal to the expected ones
  static bool areEqual(const std::vector<real>& values,
                       const std::vector<real>& expected) {
    constexpr auto eps = real(1e-12);
    for (std::size_t i = 0; i != values.size(); ++i) {
      if (std::abs(values[i] - expected[i]) > eps) {
        return false;
      }
    }
    return true;
  }  // end of areEqual
  //! \brief library containing the tested behaviour
  const std::string library;
  //! \brief rotation matrix from the global frame to the material frame
  tfel::math::tmatrix<3u, 3u, real> R;
  //! \brief components of the rotation matrix in column-major format
  std::array<real, 9u> rv;
};

TFEL_TESTS_GENERATE_PROXY(GenericBehaviourRotationFunctionsTest,
                          "GenericBehaviourRotationFunctionsTest");

int main() {
  auto& m = tfel::tests::TestManager::getTestManager();
  m.addTestOutput(std::cout);
  m.addXMLTestOutput("GenericBehaviourRotationFunctionsTest.xml");
  return m.execute().success() ? EXIT_SUCCESS : EXIT_FAILURE;
}
